import os
from datetime import datetime, timedelta, timezone
from typing import Dict, List, Optional, Sequence, Tuple, Union

from google.cloud import monitoring_v3
from google.protobuf.timestamp_pb2 import Timestamp


class ManagedMetricsMonitor:
    def __init__(self, project_id: Optional[str] = None) -> None:
        self.project_id = project_id or os.environ.get("GOOGLE_CLOUD_PROJECT")
        if not self.project_id:
            raise ValueError("project_id is required or set GOOGLE_CLOUD_PROJECT")
        self.client = monitoring_v3.MetricServiceClient()
        self.project_name = f"projects/{self.project_id}"

    @staticmethod
    def _to_timestamp(value: datetime) -> Timestamp:
        if value.tzinfo is None:
            value = value.replace(tzinfo=timezone.utc)
        ts = Timestamp()
        ts.FromDatetime(value.astimezone(timezone.utc))
        return ts

    @staticmethod
    def _build_filter(
        metric_type: str,
        resource_type: Optional[str] = None,
        metric_labels: Optional[Dict[str, str]] = None,
        resource_labels: Optional[Dict[str, str]] = None,
    ) -> str:
        parts = [f'metric.type = "{metric_type}"']
        if resource_type:
            parts.append(f'resource.type = "{resource_type}"')
        for k, v in (metric_labels or {}).items():
            parts.append(f'metric.labels.{k} = "{v}"')
        for k, v in (resource_labels or {}).items():
            parts.append(f'resource.labels.{k} = "{v}"')
        return " AND ".join(parts)

    @staticmethod
    def _normalize_point(point) -> Dict[str, Union[str, int, float, bool, Dict]]:
        interval = {
            "start_time": point.interval.start_time.ToJsonString(),
            "end_time": point.interval.end_time.ToJsonString(),
        }

        value = point.value
        kind = value.WhichOneof("value")
        if kind == "double_value":
            parsed_value = value.double_value
        elif kind == "int64_value":
            parsed_value = int(value.int64_value)
        elif kind == "bool_value":
            parsed_value = bool(value.bool_value)
        elif kind == "string_value":
            parsed_value = value.string_value
        elif kind == "distribution_value":
            dv = value.distribution_value
            parsed_value = {
                "count": int(dv.count),
                "mean": float(dv.mean),
                "sum_of_squared_deviation": float(dv.sum_of_squared_deviation),
                "bucket_counts": list(dv.bucket_counts),
            }
        else:
            parsed_value = None

        return {"interval": interval, "value": parsed_value, "value_type": kind or "unknown"}

    def query_metric_data(
        self,
        metric_type: str,
        resource_type: Optional[str] = None,
        metric_labels: Optional[Dict[str, str]] = None,
        resource_labels: Optional[Dict[str, str]] = None,
        start_time: Optional[datetime] = None,
        end_time: Optional[datetime] = None,
        minutes: int = 60,
        alignment_period_seconds: int = 300,
        per_series_aligner: str = "ALIGN_MEAN",
        cross_series_reducer: Optional[str] = None,
        group_by_fields: Optional[Sequence[str]] = None,
        page_size: int = 100,
    ) -> List[Dict]:
        end_time = end_time or datetime.now(timezone.utc)
        start_time = start_time or (end_time - timedelta(minutes=minutes))

        filter_str = self._build_filter(
            metric_type=metric_type,
            resource_type=resource_type,
            metric_labels=metric_labels,
            resource_labels=resource_labels,
        )

        interval = monitoring_v3.TimeInterval(
            start_time=self._to_timestamp(start_time),
            end_time=self._to_timestamp(end_time),
        )

        aggregation = monitoring_v3.Aggregation(
            alignment_period={"seconds": alignment_period_seconds},
            per_series_aligner=getattr(
                monitoring_v3.Aggregation.Aligner, per_series_aligner
            ),
        )

        if cross_series_reducer:
            aggregation.cross_series_reducer = getattr(
                monitoring_v3.Aggregation.Reducer, cross_series_reducer
            )
            aggregation.group_by_fields.extend(group_by_fields or [])

        results = []
        pager = self.client.list_time_series(
            request={
                "name": self.project_name,
                "filter": filter_str,
                "interval": interval,
                "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL,
                "aggregation": aggregation,
                "page_size": page_size,
            }
        )

        for series in pager:
            results.append(
                {
                    "metric": dict(series.metric.labels),
                    "metric_type": series.metric.type,
                    "resource_type": series.resource.type,
                    "resource_labels": dict(series.resource.labels),
                    "points": [self._normalize_point(p) for p in series.points],
                    "unit": series.unit,
                }
            )

        return results

    def query_gce_cpu_utilization(
        self,
        instance_id: Optional[str] = None,
        zone: Optional[str] = None,
        minutes: int = 60,
    ) -> List[Dict]:
        resource_labels = {}
        if instance_id:
            resource_labels["instance_id"] = instance_id
        if zone:
            resource_labels["zone"] = zone

        return self.query_metric_data(
            metric_type="compute.googleapis.com/instance/cpu/utilization",
            resource_type="gce_instance",
            resource_labels=resource_labels or None,
            minutes=minutes,
            alignment_period_seconds=300,
            per_series_aligner="ALIGN_MEAN",
        )
